                            "kind": "legal",
                            "source_ids": [
                                "J:EU-BANK-SUPERVISORS"
                            ],
                            "jurisdictions": [
                                "PT"
                            ],
                            "applies_when": "For banking supervision in the Single Supervisory Mechanism; not an investment, insurance or general software regulator mapping."
